dossier_19995395:
PREFIX jolux: <http://data.legilux.public.lu/resource/ontology/jolux#>
PREFIX dcterms: <http://purl.org/dc/terms/>
SELECT DISTINCT ?act ?status WHERE {
  ?act dcterms:identifier "19995395"^^<https://fedlex.data.admin.ch/datatype/dossier> ; jolux:inForceStatus ?status .
}

eli_cc_1999_404:
PREFIX jolux: <http://data.legilux.public.lu/resource/ontology/jolux#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX dcterms: <http://purl.org/dc/terms/>
SELECT DISTINCT ?lang ?title ?short ?sr ?dateDocument ?dateEntryInForce ?latestApplicability ?status ?statusLabel ?typeLabel ?dossier WHERE {
  BIND(<https://fedlex.data.admin.ch/eli/cc/1999/404> AS ?act)
  ?act jolux:isRealizedBy ?expr .
  ?expr jolux:language ?lang ; jolux:title ?title .
  OPTIONAL { ?expr jolux:titleShort ?short }
  OPTIONAL { ?act jolux:classifiedByTaxonomyEntry/skos:notation ?sr }
  OPTIONAL { ?act jolux:dateDocument ?dateDocument }
  OPTIONAL { ?act jolux:dateEntryInForce ?dateEntryInForce }
  OPTIONAL { ?act dcterms:identifier ?dossier }
  OPTIONAL { ?act jolux:inForceStatus ?status . OPTIONAL { ?status skos:prefLabel ?statusLabel FILTER(lang(?statusLabel) = "en") } }
  OPTIONAL { ?act jolux:typeDocument ?t . ?t skos:prefLabel ?typeLabel FILTER(lang(?typeLabel) = "en") }
  OPTIONAL { SELECT (MAX(?d) AS ?latestApplicability) WHERE {
    ?cons jolux:isMemberOf <https://fedlex.data.admin.ch/eli/cc/1999/404> ; jolux:dateApplicability ?d .
    FILTER(STR(?d) <= SUBSTR(STR(NOW()), 1, 10)) } }
}

